-- 补发合并：批次、行裁决与来源版本状态。启动由 metadata.create_all 建表，此文件为规范迁移留档。
CREATE TABLE IF NOT EXISTS import_batches (id SERIAL PRIMARY KEY,batch_no VARCHAR(64) UNIQUE NOT NULL,source VARCHAR(20) NOT NULL,content_hash VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL,total_rows INTEGER NOT NULL,added INTEGER NOT NULL,revised INTEGER NOT NULL,stale INTEGER NOT NULL,quarantined INTEGER NOT NULL,duplicate INTEGER NOT NULL,error TEXT NOT NULL,actor VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL,finished_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS import_rows (id SERIAL PRIMARY KEY,batch_id INTEGER NOT NULL REFERENCES import_batches(id),row_no INTEGER NOT NULL,code VARCHAR(50) NOT NULL,version INTEGER NOT NULL,payload JSON NOT NULL,decision VARCHAR(20) NOT NULL,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_states (id SERIAL PRIMARY KEY,code VARCHAR(50) NOT NULL,source VARCHAR(20) NOT NULL,version INTEGER NOT NULL,payload JSON NOT NULL,CONSTRAINT uq_source_states_code_source UNIQUE (code,source));
